import java.util.*; public class Q12_VehicleRentalSystem{static class Vehicle{String r,b;double rate;Vehicle(String r,String b,double x){this.r=r;this.b=b;rate=x;}double rent(){return rate;}}static class Car extends Vehicle{Car(String r,String b,double x){super(r,b,x);}double rent(){return rate*1.5;}}static class Bike extends Vehicle{Bike(String r,String b,double x){super(r,b,x);}double rent(){return rate*1.2;}}public static void main(String[]x){Scanner s=new Scanner(System.in);while(s.hasNextLine()){String[]p=s.nextLine().split(",");Vehicle v=p[0].equalsIgnoreCase("Car")?new Car(p[1],p[2],Double.parseDouble(p[3])):new Bike(p[1],p[2],Double.parseDouble(p[3]));System.out.println(p[0]+" "+p[1]+" "+p[2]+" Rent: "+v.rent());}}}
